const cfg = $input.first().json;
const text = (value) => typeof value === 'string' ? value.trim() : '';
let advancedInput;
try {
  advancedInput = JSON.parse(text(cfg.advancedInputJson) || '{}');
} catch (error) {
  throw new Error(`Configuration: advancedInputJson must be valid JSON (${error.message})`);
}
if (!advancedInput || typeof advancedInput !== 'object' || Array.isArray(advancedInput)) {
  throw new Error('Configuration: advancedInputJson must contain one JSON object');
}
const actorInput = {
  schemaVersion: 'nomad-agent-job-search-input-v1',
  keyword: text(cfg.keyword),
  location: text(cfg.location),
  postedWithin: text(cfg.postedWithin),
  workArrangements: text(cfg.workArrangementsCsv).split(',').map(value => value.trim()).filter(Boolean),
  maxItems: Number(cfg.maxItems),
  translateToEnglish: false,
  aiEnrichment: { enabled: false, accuracy: 'silver' },
  includeRaw: false,
  dedupe: { enabled: false, key: '' },
  analyticsEnabled: false,
  ...advancedInput,
};
if (actorInput.schemaVersion !== 'nomad-agent-job-search-input-v1') {
  throw new Error('Configuration: actor input schemaVersion must be nomad-agent-job-search-input-v1');
}
if (!new Set(['1h', '24h', '7d', '30d', 'any']).has(actorInput.postedWithin)) {
  throw new Error('Configuration: postedWithin must be 1h, 24h, 7d, 30d, or any');
}
if (!Array.isArray(actorInput.workArrangements)) {
  throw new Error('Configuration: workArrangements must be an array');
}
const invalidArrangements = actorInput.workArrangements.filter(value => !new Set(['remote', 'hybrid', 'onsite']).has(value));
if (invalidArrangements.length) throw new Error(`Configuration: invalid work arrangement(s): ${invalidArrangements.join(', ')}`);
if (!Number.isInteger(actorInput.maxItems) || actorInput.maxItems < 0 || actorInput.maxItems > 200) {
  throw new Error('Configuration: maxItems must be an integer from 0 to 200');
}
const chargeCap = Number(cfg.maxTotalChargeUsd);
if (!Number.isFinite(chargeCap) || chargeCap <= 0 || chargeCap > 10) {
  throw new Error('Configuration: maxTotalChargeUsd must be greater than 0 and at most 10');
}
if (!/^\d+\.\d+\.\d+$/.test(text(cfg.actorBuild))) {
  throw new Error('Configuration: actorBuild must be a pinned version such as 0.6.45');
}
const retryLimit = Number(cfg.maxRescheduleRetries);
if (!Number.isInteger(retryLimit) || retryLimit < 0 || retryLimit > 1) {
  throw new Error('Configuration: maxRescheduleRetries must be 0 or 1');
}
const spreadsheetId = text(cfg.googleSpreadsheetId);
if (spreadsheetId.startsWith('REPLACE_WITH_') || !/^[A-Za-z0-9_-]{20,}$/.test(spreadsheetId)) {
  throw new Error('Configuration: replace googleSpreadsheetId with the ID from your Google Sheets URL');
}
if (!text(cfg.googleSheetName)) throw new Error('Configuration: googleSheetName is required');
return [{ json: { ...cfg, actorInput } }];

const envelope = $input.first().json;
const run = envelope && typeof envelope === 'object' ? (envelope.data || envelope) : {};
const expectedBuild = String($('Configuration').first().json.actorBuild || '').trim();
if (run.status !== 'SUCCEEDED' || run.exitCode !== 0) {
  throw new Error(`Actor run ${run.id || 'unknown'} ended with ${run.status || 'unknown'} (exitCode=${run.exitCode ?? 'unknown'}); failed terminal runs cannot be retried from RUN-SUMMARY`);
}
if (run.buildNumber !== expectedBuild) {
  throw new Error(`Actor run used build ${run.buildNumber || 'unknown'}; expected ${expectedBuild}`);
}
if (!run.id || !run.defaultDatasetId) {
  throw new Error('Successful Actor run is missing its run ID or default dataset ID');
}
return [{ json: {
  runId: run.id,
  defaultDatasetId: run.defaultDatasetId,
  datasetItemCount: run.stats && Number.isInteger(run.stats.datasetItems) ? run.stats.datasetItems : null
} }];

const envelope = $input.first().json;
const summary = envelope && typeof envelope === 'object' ? (envelope.body || envelope.data || envelope) : null;
const exactKeys = (value, expected, path) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`${path} must be an object`);
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (JSON.stringify(actual) !== JSON.stringify(wanted)) throw new Error(`${path} must be a closed v4 object`);
};
const count = (value, path) => {
  if (!Number.isInteger(value) || value < 0 || value > 2147483647) throw new Error(`${path} must be a nonnegative integer`);
  return value;
};
exactKeys(summary, ['schemaVersion', 'status', 'startedAt', 'finishedAt', 'resultsLimited', 'delivered', 'retry'], 'RUN-SUMMARY');
if (summary.schemaVersion !== 'nomad-agent-run-summary-v4') throw new Error(`Unsupported RUN-SUMMARY schema: ${summary.schemaVersion}`);
if (!['succeeded', 'empty', 'partial'].includes(summary.status)) throw new Error('RUN-SUMMARY status is unsupported');
const startedMs = Date.parse(summary.startedAt);
const finishedMs = Date.parse(summary.finishedAt);
if (!Number.isFinite(startedMs) || !Number.isFinite(finishedMs) || finishedMs < startedMs) throw new Error('RUN-SUMMARY timestamps are invalid');
if (typeof summary.resultsLimited !== 'boolean') throw new Error('RUN-SUMMARY resultsLimited must be boolean');
const delivered = count(summary.delivered, 'RUN-SUMMARY.delivered');
exactKeys(summary.retry, ['recommended', 'afterSeconds'], 'RUN-SUMMARY.retry');
if (typeof summary.retry.recommended !== 'boolean') throw new Error('RUN-SUMMARY retry.recommended must be boolean');
let delay = 0;
if (summary.retry.recommended) {
  if (summary.status !== 'partial') throw new Error('Only partial RUN-SUMMARY may recommend retry');
  if (!Number.isInteger(summary.retry.afterSeconds) || summary.retry.afterSeconds < 1 || summary.retry.afterSeconds > 3600) throw new Error('RUN-SUMMARY retry.afterSeconds must be 1 through 3600');
  delay = summary.retry.afterSeconds;
} else if (summary.retry.afterSeconds !== null) {
  throw new Error('Non-recommended retry requires afterSeconds=null');
}
if (summary.status === 'empty' && (delivered !== 0 || summary.resultsLimited || summary.retry.recommended)) throw new Error('Empty RUN-SUMMARY invariants failed');
if (summary.status !== 'empty' && delivered < 1) throw new Error('Usable RUN-SUMMARY requires at least one delivered job');
if (summary.status === 'succeeded' && summary.retry.recommended) throw new Error('Succeeded RUN-SUMMARY cannot recommend retry');
const retryLimit = Number($('Configuration').first().json.maxRescheduleRetries);
const retryAttempt = $runIndex;
const retryRecommended = summary.retry.recommended && retryAttempt < retryLimit;
return [{ json: {
  ...$('Validate terminal run').first().json,
  runSummary: summary,
  retryRecommended,
  retryAfterSeconds: delay,
  retryAttempt,
  retryExhausted: summary.retry.recommended && !retryRecommended
} }];

const incoming = $input.all();
let count = 0;
for (const item of incoming) {
  const value = item.json;
  if (Array.isArray(value)) count += value.length;
  else if (value && Array.isArray(value.body)) count += value.body.length;
  else if (value && value.schemaVersion === 'nomad-agent-job-v1') count += 1;
  else if (value && Object.keys(value).length === 0) continue;
  else throw new Error('Dataset response shape is invalid');
}
const expected = $('Validate run status').first().json.runSummary.delivered;
if (count !== expected) throw new Error(`RUN-SUMMARY delivered=${expected} but fetched dataset contains ${count} jobs`);
return incoming;

const ROOTS = ['custom', 'data', 'identity', 'llm', 'raw', 'schemaVersion'];

const compactArray = (value, path) => {
  if (value === null || value === undefined) return null;
  if (!Array.isArray(value)) throw new Error(`${path} must be an array or null`);
  return JSON.stringify(value);
};

const objectOrEmpty = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};

const locationLabel = (location) => {
  const value = objectOrEmpty(location);
  if (typeof value.raw === 'string' && value.raw.trim()) return value.raw.trim();
  return [...new Set([value.city, value.region, value.countryName].filter(part => typeof part === 'string' && part.trim()).map(part => part.trim()))].join(', ') || null;
};

const incoming = $input.all().map(item => item.json);
const jobs = [];
for (const value of incoming) {
  if (Array.isArray(value)) jobs.push(...value);
  else if (value && Array.isArray(value.body)) jobs.push(...value.body);
  else if (value && value.schemaVersion === 'nomad-agent-job-v1') jobs.push(value);
  else if (value && Object.keys(value).length === 0) continue;
  else throw new Error('Apify response did not contain nomad-agent-job-v1 records');
}

const seen = new Set();
const output = [];
for (const record of jobs) {
  if (!record || typeof record !== 'object' || Array.isArray(record)) throw new Error('Actor row must be an object');
  const actualRoots = Object.keys(record).sort();
  if (JSON.stringify(actualRoots) !== JSON.stringify(ROOTS)) throw new Error(`Actor row has unexpected roots: ${actualRoots.join(', ')}`);
  if (record.schemaVersion !== 'nomad-agent-job-v1') throw new Error(`Unsupported schemaVersion: ${record.schemaVersion}`);

  const identity = objectOrEmpty(record.identity);
  const data = objectOrEmpty(record.data);
  const company = objectOrEmpty(data.company);
  const classification = objectOrEmpty(data.classification);
  const employment = objectOrEmpty(data.employment);
  const application = objectOrEmpty(data.application);
  const seniority = objectOrEmpty(data.seniority);
  const compensation = objectOrEmpty(data.compensation);
  const llm = objectOrEmpty(record.llm);
  const raw = objectOrEmpty(record.raw);
  const locations = data.locations;
  if (locations !== null && locations !== undefined && !Array.isArray(locations)) throw new Error('data.locations must be an array or null');
  const firstLocation = Array.isArray(locations) && locations.length ? objectOrEmpty(locations[0]) : {};
  const stablePart = identity.externalId || identity.url;
  if (!identity.source || !stablePart) throw new Error('identity.source and identity.externalId or identity.url are required');
  const jobKey = `${identity.source}:${stablePart}`;
  if (seen.has(jobKey)) continue;
  seen.add(jobKey);

  output.push({ json: {
    schemaVersion: 'nomad-agent-flat-job-v1',
    jobKey,
    source: identity.source,
    identityExternalId: identity.externalId ?? null,
    jobUrl: identity.url ?? null,
    title: data.title ?? null,
    companyName: company.name ?? null,
    companySourceId: company.sourceId ?? null,
    companyUrl: company.url ?? null,
    locationText: Array.isArray(locations) ? locations.map(locationLabel).filter(Boolean).join(' | ') || null : null,
    countryCode: firstLocation.countryCode ?? null,
    city: firstLocation.city ?? null,
    region: firstLocation.region ?? null,
    workArrangements: compactArray(employment.workArrangements, 'data.employment.workArrangements'),
    workSchedules: compactArray(employment.workSchedules, 'data.employment.workSchedules'),
    contractTypes: compactArray(employment.contractTypes, 'data.employment.contractTypes'),
    postedAt: application.postedAt ?? null,
    applicationDeadline: application.deadline ?? null,
    applicationUrl: application.url ?? null,
    applicationEmail: application.email ?? null,
    directApply: application.directApply ?? null,
    seniorityLevels: compactArray(seniority.levels, 'data.seniority.levels'),
    industries: compactArray(classification.industries, 'data.classification.industries'),
    jobFunctions: compactArray(classification.jobFunctions, 'data.classification.jobFunctions'),
    salaryCurrency: compensation.currency ?? null,
    salaryExact: compensation.exact ?? null,
    salaryMinimum: compensation.minimum ?? null,
    salaryMaximum: compensation.maximum ?? null,
    salaryPeriod: compensation.period ?? null,
    salaryRaw: compensation.raw ?? null,
    descriptionText: raw.description ?? null,
    llmStatus: llm.status ?? null
  } });
}
return output;

const envelope = $input.first().json;
const run = envelope && typeof envelope === 'object' ? (envelope.data || envelope) : {};
if (!run.id || typeof run.status !== 'string') {
  throw new Error('Apify returned no run ID or run status');
}
return [{ json: run }];
